import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)

DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('APP_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        password_hash TEXT,
        api_key TEXT,
        last_login TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        timestamp REAL,
        details TEXT
    )''')
    db.commit()
    db.close()

def verify_session_token(token):
    """Verify HMAC-based session token"""
    if not token:
        return None
    parts = token.split('.')
    if len(parts) != 3:
        return None
    user_id, timestamp, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), f"{user_id}.{timestamp}".encode(), hashlib.sha256).hexdigest()[:16]
    if not hmac.compare_digest(sig, expected):
        return None
    if time.time() - float(timestamp) > 86400:
        return None
    return int(user_id)

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')
    limit = request.args.get('limit', '20')

    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'role', 'last_login']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query with user input for search value
    query = f"SELECT id, username, email, role, last_login FROM users WHERE {field} LIKE '%{value}%' ORDER BY id LIMIT {limit}"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, timestamp, details) VALUES (?, ?, ?)",
            ('search', time.time(), f"field={field}, q={value}")
        )
        db.commit()

        return jsonify({'results': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID"""
    db = get_db()
    user = db.execute(
        "SELECT id, username, email, role, last_login FROM users WHERE id = ?",
        (user_id,)
    ).fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account"""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    password_hash = hashlib.sha256(data.get('password', '').encode()).hexdigest()
    api_key = hashlib.sha256(os.urandom(32)).hexdigest()

    try:
        db = get_db()
        db.execute(
            "INSERT INTO users (username, email, password_hash, api_key) VALUES (?, ?, ?, ?)",
            (data['username'], data['email'], password_hash, api_key)
        )
        db.commit()
        return jsonify({'status': 'created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
